cat > app/pages/contact.vue <<'EOF'
<script setup lang="ts">
import { readBody } from 'h3'

useHead({ title: 'Contact | Bookshelf' })

interface ContactState {
  values: ContactValues
  errors: ContactErrors
  success: string
}

// Without JavaScript the form posts to this page: the server validates the
// submitted values and renders the errors or the success message.
const { data: submitted } = await useAsyncData('contact-submission', async (): Promise<ContactState | null> => {
  if (import.meta.server) {
    const event = useRequestEvent()
    if (event?.method === 'POST') {
      const values = normalizeContact(await readBody(event))
      const errors = validateContact(values)
      if (hasContactErrors(errors)) {
        return { values, errors, success: '' }
      }
      return { values: { name: '', email: '', message: '' }, errors: {}, success: contactSuccessMessage(values.name) }
    }
  }
  return null
})

const form = reactive<ContactValues>({ ...(submitted.value?.values ?? { name: '', email: '', message: '' }) })
const errors = ref<ContactErrors>(submitted.value?.errors ?? {})
const success = ref(submitted.value?.success ?? '')
const sending = ref(false)

type ContactResponse = { ok: true, message: string } | { ok: false, errors: ContactErrors }

async function onSubmit() {
  success.value = ''
  errors.value = validateContact(form)
  if (hasContactErrors(errors.value)) return

  sending.value = true
  try {
    const response = await $fetch<ContactResponse>('/api/contact', {
      method: 'POST',
      body: { ...form },
      ignoreResponseError: true
    })
    if (response.ok) {
      success.value = response.message
      Object.assign(form, { name: '', email: '', message: '' })
    } else {
      errors.value = response.errors
    }
  } finally {
    sending.value = false
  }
}
</script>

<template>
  <div>
    <h1>Contact</h1>

    <p v-if="success" role="status" class="success">{{ success }}</p>

    <form method="post" action="/contact" novalidate class="contact-form" @submit.prevent="onSubmit">
      <div class="field">
        <label for="contact-name">Name</label>
        <input
          id="contact-name"
          v-model="form.name"
          type="text"
          name="name"
          autocomplete="name"
          :aria-invalid="errors.name ? 'true' : undefined"
          :aria-describedby="errors.name ? 'contact-name-error' : undefined"
        >
        <p v-if="errors.name" id="contact-name-error" class="error">{{ errors.name }}</p>
      </div>

      <div class="field">
        <label for="contact-email">Email</label>
        <input
          id="contact-email"
          v-model="form.email"
          type="email"
          name="email"
          autocomplete="email"
          :aria-invalid="errors.email ? 'true' : undefined"
          :aria-describedby="errors.email ? 'contact-email-error' : undefined"
        >
        <p v-if="errors.email" id="contact-email-error" class="error">{{ errors.email }}</p>
      </div>

      <div class="field">
        <label for="contact-message">Message</label>
        <textarea
          id="contact-message"
          v-model="form.message"
          name="message"
          rows="5"
          :aria-invalid="errors.message ? 'true' : undefined"
          :aria-describedby="errors.message ? 'contact-message-error' : undefined"
        />
        <p v-if="errors.message" id="contact-message-error" class="error">{{ errors.message }}</p>
      </div>

      <button type="submit" :disabled="sending">Send</button>
    </form>
  </div>
</template>

<style scoped>
.contact-form {
  display: grid;
  gap: 1rem;
  max-width: 30rem;
}
.field {
  display: grid;
  gap: 0.25rem;
}
.field p {
  margin: 0;
}
.error {
  color: #b00020;
}
.success {
  color: #1b6e2d;
  font-weight: bold;
}
</style>
EOF
bun run build 2>&1 | tail -30
